<?php
require_once __DIR__.'/../includes/db_connect.php';require_once __DIR__.'/../includes/auth.php';requireRole('instructor');
$st=$pdo->prepare("SELECT a.score,a.attempt_number,a.submitted_at,q.title,c.course_name,u.name,u.surname,u.email FROM quiz_attempts a JOIN quizzes q ON q.quiz_id=a.quiz_id JOIN courses c ON c.course_id=q.course_id JOIN users u ON u.user_id=a.user_id JOIN course_assignments ca ON ca.course_id=c.course_id WHERE ca.instructor_id=? ORDER BY a.submitted_at DESC");$st->execute([$_SESSION['user_id']]);$results=$st->fetchAll();$pageTitle='Quiz Results';require __DIR__.'/../includes/header.php';
?><div class="page-heading"><div><div class="eyebrow">INSTRUCTOR PORTAL</div><h1>Quiz Results</h1><p>Review learner performance in your assigned courses.</p></div></div><section class="dashboard-card"><div class="table-container"><table><thead><tr><th>Learner</th><th>Quiz</th><th>Course</th><th>Attempt</th><th>Score</th><th>Submitted</th></tr></thead><tbody><?php if(!$results):?><tr><td colspan="6">No quiz attempts yet.</td></tr><?php else:foreach($results as $r):?><tr><td><?=e($r['name'].' '.$r['surname'])?><br><small><?=e($r['email'])?></small></td><td><?=e($r['title'])?></td><td><?=e($r['course_name'])?></td><td><?=e($r['attempt_number'])?></td><td><strong><?=e($r['score'])?>%</strong></td><td><?=e($r['submitted_at'])?></td></tr><?php endforeach;endif;?></tbody></table></div></section><?php require __DIR__.'/../includes/footer.php'; ?>
